js.text:

function grid$acrecord(f){
  this.constructor(f);
}
grid$acrecord.prototype = new DirEvent();
grid$acrecord.prototype.afterInit = function(renderType){
  var p = this._dir;
	p.find(".toolbar-approve").attr('title', p.msg('approve'))
}
grid$acrecord.prototype.beforeButtonGridClick = function (id, gindex) {

  var msg, p = this._dir, g = p.grid(gindex), dt = g.data, itemls = p.selectedItems(), xstatus = p.options._status;
  switch (id) {

    case 'approve':
      msg = (xstatus ==1)? p.msg('msg1'): (xstatus == 9)? p.msg('msg3'):p.msg('msg2');
      if (itemls.count() > 0)
        $.question(msg, $.msg.get("QuestionTitle"), p, function (q, v) {
          q._close();
          if (v){
            p.request('Approve', '', [["tblKeys", "T", itemls.sqlval()], ['xstatus', 'I', xstatus]], function(pp, d, run){
              if (run) {
                p._refresh();
                p.clearSelectedItems();
              }
            });
          }
        });
      return false;
      break;
    default:
      break;
  }
  return true;
}

css.text:

.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
